import React from 'react';

export default function Navbar({
  onLoginClick,
  isLoggedIn,
  studentName,
  setCurrentPage,
  currentPage
}) {

  const getStyle = (page) => ({
    fontSize: '16px',
    fontWeight: '600',
    cursor: 'pointer',
    color: currentPage === page ? '#ffffff' : '#d9f5e5',
    borderBottom: currentPage === page ? '2px solid #ffffff' : 'none',
    paddingBottom: '4px',
    transition: '0.3s'
  });

  return (
    <nav
      style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: '14px 45px',
        background: 'linear-gradient(135deg, #1b4332, #2a9d8f)',
        boxShadow: '0 4px 10px rgba(0,0,0,0.15)',
        position: 'sticky',
        top: '0',
        zIndex: '1000'
      }}
    >

      {/* Logo */}
      <div
        style={{ cursor: 'pointer' }}
        onClick={() => setCurrentPage('Home')}
      >
        <img
          src={require('../logo.png')}
          alt="Logo"
          style={{
            height: '65px',
            width: 'auto'
          }}
        />
      </div>

      {/* Menu */}
      <div
        style={{
          display: 'flex',
          gap: '35px',
          alignItems: 'center'
        }}
      >
        <span
          style={getStyle('Home')}
          onClick={() => setCurrentPage('Home')}
        >
          Home
        </span>

        <span
          style={getStyle('Classes')}
          onClick={() => setCurrentPage('Classes')}
        >
          Classes
        </span>

        <span
          style={getStyle('Teachers')}
          onClick={() => setCurrentPage('Teachers')}
        >
          Teachers
        </span>

        <span
          style={getStyle('About')}
          onClick={() => setCurrentPage('About')}
        >
          About
        </span>
      </div>

      {/* Right Side */}
      <div>
        {!isLoggedIn ? (
          <button
            onClick={onLoginClick}
            style={{
              padding: '10px 28px',
              backgroundColor: '#ffffff',
              color: '#1b4332',
              border: 'none',
              borderRadius: '10px',
              fontSize: '15px',
              fontWeight: '700',
              cursor: 'pointer',
              transition: '0.3s'
            }}
          >
            Login
          </button>
        ) : (
          <span
            style={{
              fontWeight: '700',
              color: '#ffffff',
              fontSize: '16px'
            }}
          >
            👤 {studentName}
          </span>
        )}
      </div>

    </nav>
  );
}
